#include <iostream>
#include <thread>

int main() {
    int n = 0;
    std::cin >> n;
    long long lower_total = 0;
    long long upper_total = 0;
    std::thread worker([&lower_total, n]() {
        for (int i = 1; i <= n / 2; i++) {
            lower_total += i;
        }
    });
    for (int i = n / 2 + 1; i <= n; i++) {
        upper_total += i;
    }
    worker.join();
    std::cout << lower_total + upper_total << std::endl;
    return 0;
}
